/** 
 * Returns an internationalized string loaded from a resource bundle. The locale used will be the locale specified by JiveGlobals.getLocale().
 * @param key the key to use for retrieving the string from theappropriate resource bundle.
 * @return the localized string.
 */
public static String getLocalizedString(String key){
  Locale locale=JiveGlobals.getLocale();
  try {
    ResourceBundle bundle=ResourceBundle.getBundle(resourceBaseName,locale);
    return getLocalizedString(key,locale,null,bundle);
  } catch (MissingResourceException e) {
    // Handle missing resource bundle
    return "??" + key + "??";
  } catch (NullPointerException e) {
    // Handle null parameters
    return "??" + key + "??";
  }
}
